let out = ''
if (mode === 'rounds') {
  for (const r of result.rounds) {
    out += `round ${r.number}: ${r.lines.map((c) => `${c.name}=${c.votes}`).concat(`exhausted=${r.exhausted}`).join(' ')}\n`
    if (r.eliminated) out += `eliminated ${r.eliminated}\n`
  }
} else {
  out += `rounds ${result.rounds.length}\n`
}
out += result.winner ? `winner ${result.winner}\n` : 'no winner\n'
