EOF
cat > src/parse.js <<'EOF'
function fail(msg) {
  const e = new Error(msg)
  e.election = true
  throw e
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (!candidates) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (!candidates) fail('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // Map name -> votes per round
  const rounds = []
  for (let number = 1; ; number++) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const lines = [...votes].map(([name, v]) => ({ name, votes: v })).sort((a, b) =>
      a.votes > b.votes ? -1 : a.votes < b.votes ? 1 : a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
    const round = { number, lines, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = lines[0]
    if (top.votes * 2n > active) return { rounds, winner: top.name }
    let set = lines.filter((l) => l.votes === lines[lines.length - 1].votes).map((l) => l.name)
    for (let r = 0; set.length > 1 && r < history.length; ) {
      const vs = set.map((c) => history[r].get(c))
      const min = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.every((v) => v === min)) { r++; continue }
      set = set.filter((c, k) => vs[k] === min)
      r = 0
    }
    const out = set.reduce((a, b) => (b > a ? b : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
